from kfp import dsl
from kfp.v2 import compiler
from google.cloud import aiplatform

@dsl.component(base_image="python:3.11")
def preprocess(data_path: str, output_path: dsl.Output[dsl.Dataset]):
    # data preparation logic here
    pass

@dsl.component(base_image="python:3.11")
def train(dataset: dsl.Input[dsl.Dataset], model: dsl.Output[dsl.Model]):
    # training logic here
    pass

@dsl.pipeline(name="my-training-pipeline")
def pipeline(data_path: str):
    prep = preprocess(data_path=data_path)
    train(dataset=prep.outputs["output_path"])

compiler.Compiler().compile(pipeline_func=pipeline, package_path="pipeline.yaml")

aiplatform.init(project="my-project", location="us-central1")
job = aiplatform.PipelineJob(display_name="my-run", template_path="pipeline.yaml")
job.run()

from google.cloud import documentai

client = documentai.DocumentProcessorServiceClient()

processor_name = (
    "projects/my-project/locations/us/processors/my-invoice-processor-id"
)

with open("invoice.pdf", "rb") as f:
    raw_document = documentai.RawDocument(
        content=f.read(), mime_type="application/pdf"
    )

result = client.process_document(
    request=documentai.ProcessRequest(
        name=processor_name, raw_document=raw_document
    )
)

for entity in result.document.entities:
    print(entity.type_, entity.mention_text, entity.confidence)
